<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$u=v700_require_user();$uid=(int)$u['id'];$hotels=v700_rows("SELECT b.*,h.name hotel_name,r.name room_name FROM hotel_bookings_v700 b JOIN tourism_hotels_v700 h ON h.id=b.hotel_id JOIN tourism_hotel_rooms_v700 r ON r.id=b.room_id WHERE b.tenant_id=? AND b.user_id=? ORDER BY b.id DESC",[v700_tid(),$uid]);$rests=v700_rows("SELECT b.*,r.name restaurant_name FROM restaurant_bookings_v700 b JOIN tourism_restaurants_v700 r ON r.id=b.restaurant_id WHERE b.tenant_id=? AND b.user_id=? ORDER BY b.id DESC",[v700_tid(),$uid]);$tours=v700_rows("SELECT b.*,p.title package_title FROM tourism_package_bookings_v700 b JOIN tourism_packages_v700 p ON p.id=b.package_id WHERE b.tenant_id=? AND b.user_id=? ORDER BY b.id DESC",[v700_tid(),$uid]);v700_public_header('My Tourism Bookings','Hotel, restaurant and tour bookings.','tourism');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">MY BOOKINGS</span><h1>Stay, dining & tour dashboard</h1><p>Track every tourism booking made through ShahkotPK.</p></div></section><section class="v700-section soft"><div class="v700-shell"><div class="v700-account-grid"><a href="#hotel"><b><?=count($hotels)?></b><span>Hotel Bookings</span></a><a href="#restaurant"><b><?=count($rests)?></b><span>Restaurant Reservations</span></a><a href="#tour"><b><?=count($tours)?></b><span>Tour Bookings</span></a><a href="/tourism.php"><b>+</b><span>Explore Tourism</span></a></div><section class="v700-panel" id="hotel"><h2>Hotels</h2><div class="v700-list"><?php foreach($hotels as $b):?><div class="v700-row"><i>🏨</i><span><b><?=e($b['hotel_name'])?> · <?=e($b['room_name'])?></b><small><?=e($b['booking_no'])?> · <?=e($b['check_in'])?> → <?=e($b['check_out'])?></small></span><?=v700_status_badge($b['status'])?></div><?php endforeach;?></div></section><section class="v700-panel" id="restaurant"><h2>Restaurant Reservations</h2><div class="v700-list"><?php foreach($rests as $b):?><div class="v700-row"><i>🍽</i><span><b><?=e($b['restaurant_name'])?></b><small><?=e($b['booking_no'])?> · <?=e($b['booking_date'])?> <?=e($b['booking_time'])?> · <?=number_format((int)$b['guests'])?> guests</small></span><?=v700_status_badge($b['status'])?></div><?php endforeach;?></div></section><section class="v700-panel" id="tour"><h2>Tour Packages</h2><div class="v700-list"><?php foreach($tours as $b):?><div class="v700-row"><i>🧭</i><span><b><?=e($b['package_title'])?></b><small><?=e($b['booking_no'])?> · <?=e($b['travel_date'])?> · <?=number_format((int)$b['people'])?> people</small></span><?=v700_status_badge($b['status'])?></div><?php endforeach;?></div></section></div></section></main><?php v700_public_footer(); ?>
